import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late CurrencyRepository _repository;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = false;
  bool _isLoadingMore = false;
  String _searchText = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    _repository = context.read<CurrencyRepository>();
    _loadInitialPage();
  }

  Future<void> _loadInitialPage() async {
    final CurrencyPage page = await _repository.fetchRates(const CurrencyPageRequest());
    final List<CurrencyModel> value = page.items;

    setState(() {
      _allCurrencies = value;
      _currentPage = 0;
      _hasMore = page.hasMore;
    });

    _filteredCurrenciesNotifier.value = value;
    _fadeController.forward(); // запускаем анимацию

    _repository.saveCurrencyList(value);
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;
    setState(() => _isLoadingMore = true);

    final nextPage = _currentPage + 1;
    final CurrencyPage page = await _repository.fetchRates(
      CurrencyPageRequest(page: nextPage),
    );

    if (!mounted) return;

    setState(() {
      _allCurrencies.addAll(page.items);
      _currentPage = nextPage;
      _hasMore = page.hasMore;
      _isLoadingMore = false;
    });

    // Если пользователь ввёл текст поиска — обновляем отфильтрованный список.
    final query = _searchText.toLowerCase();
    if (query.isNotEmpty) {
      _filterCurrencies(query);
    } else {
      _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    _searchText = query;
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          final bool initialLoading = data.isEmpty && !_hasMore;

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: (query) {
                    if (query.isEmpty) _searchText = '';
                    _filterCurrencies(query);
                  }),
                ),
                Expanded(
                  child: initialLoading
                      ? const Center(child: CircularProgressIndicator())
                      : ListView(
                          padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                          children: [
                            for (int i = 0; i < data.length; i++) ...[
                              Padding(
                                key: ValueKey(data[i].id),
                                padding: i == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                                child: CurrencyCard(model: data[i]),
                              ),
                            ],
                            if (_isLoadingMore)
                              const Padding(
                                padding: EdgeInsets.only(top: 20, bottom: 8),
                                child: Center(child: CircularProgressIndicator()),
                              ),
                            if (!_isLoadingMore && _hasMore)
                              Padding(
                                padding: const EdgeInsets.symmetric(vertical: 16),
                                child: Center(
                                  child: ElevatedButton(
                                    onPressed: _loadMore,
                                    child: Text(context.loc.loadMore),
                                  ),
                                ),
                              ),
                          ],
                        ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

